#!/usr/bin/env python3
# =====================================================================
#  apply_tsg_wing_guard.py  —  fence TSG_WING_GUARD_20261111
#
#  2026-11-11 09:16 Tigris (paper, 10 lots) entered L1 SELL CE, L2 SELL PE,
#  L3 BUY CE — the L4 BUY PE hedge was missing and nothing said so.
#  Cause: TSG takes its entry chain from IC's snapshot_weekly_chain(),
#  which keeps only strikes within spot ± 1500. With spot ~25,350 and 4
#  sessions to expiry, put skew put the first PE <= the ₹8 wing cap below
#  that band (the ₹8 CE wing, 26800, sat ~1,450 out — on the edge too).
#  plan_entry() treats "no wing <= cap" as "wing absent — allowed" and the
#  manager never looked, so the day ran an unhedged short put.
#
#   ic_selection.py   snapshot_weekly_chain(strike_range=None) — optional
#                     band; None = ±1500, so IC/ORB/BRK/EMC/GC are unchanged
#   tsg_engine.py     TSG asks for ±3000 (cfg chain_strike_range), ~242
#                     symbols, still ONE kite.quote call
#   tsg_live_core.py  wing with nothing <= cap → cheapest real strike
#                     further OTM than its short (the backtest's fail-open
#                     rule); every absent/fallback wing goes to wing_notes
#   tsg_manager.py    wing notes → audit [TSG][WING] + bell/Telegram alert
#                     (TSG_WING_FALLBACK warning / TSG_WING_MISSING error,
#                     paper alerts stay off Telegram per alert routing);
#                     a wing still ABSENT → NO ENTRY that day (fail closed;
#                     cfg wing_absent_policy=ENTER restores the old shape,
#                     with an error alert); ENTERED + Telegram card show it
#   tests             backend/app/engine/tsg/test_tsg_wing_guard.py (new,
#                     replays the 11-Nov chain shape, 24 checks)
#
#  Normal days: identical picks (the wider band only adds cheaper strikes
#  further out; "highest premium <= cap" lands on the same contracts).
#  Today's open paper book is NOT touched by this script.
#
#  Run ONLY this script, outside market hours:
#     cd ~/dev/scalp-app && python3 apply_tsg_wing_guard.py
#  Options: --repo PATH  --skip-tests  --allow-dirty  --rollback
#  Then: ./desktop/build-scalp.sh both, restart the app.
# =====================================================================
import base64, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile, zlib

FENCE = "TSG_WING_GUARD_20261111"
ITEMS = json.loads(r'''[{"path": "backend/app/engine/ic/ic_selection.py", "orig": "4836a07d353e65836dd0f5b58ce3620f21f3ba011a6216b96fae152004c9dd33", "new": "2aac0b205b4a1e2d38269360ff94ab509569debf458725e7a38fedf080b0b1a0", "blob": ""}, {"path": "backend/app/engine/tsg/tsg_engine.py", "orig": "002c3ff8d8b950499182bb37a89819e8eb941dbd81c17c57c21c387db78d72de", "new": "96b5e7dc2fb52999f123a351df35eed8a1d8df035f94adb7fe1fd89aea1d91d2", "blob": ""}, {"path": "backend/app/engine/tsg/tsg_live_core.py", "orig": "4371045f490e7e47643fe00d82d696b7a7988aa748abb5761ecb7a93de639e9b", "new": "6c29a7c5ab2904bf8f2402ba4abc5c6a182b192e38cc2ab7c8f5d383fc2cd280", "blob": ""}, {"path": "backend/app/engine/tsg/tsg_manager.py", "orig": "048de9fb848facabb5837887786d5c159f616b2fb446352878e8e7211af857a0", "new": "b8e1fdb9d84e82e9f431fea002c8b8e52e42c24b57fa4b5b702f81bb6770f957", "blob": ""}, {"path": "backend/app/engine/tsg/test_tsg_wing_guard.py", "orig": null, "new": "d2ff359e8ee15736d61abf03c9ef33ddc9eec2a799d6eac0d4db9fee0608be99", "blob": ""}]''')
BUILD_COPIES = {"backend/": "desktop/src-tauri/backend/", "frontend/": "desktop/src-tauri/frontend/"}
TESTS = ["app/engine/tsg/test_tsg_wing_guard.py", "app/engine/tsg/test_tsg_live_core.py",
         "app/engine/tsg/test_tsg_e2e.py", "app/engine/tsg/test_tsg_exit_confirm.py",
         "app/engine/tsg/test_tsg_sl_per_lot.py"]


def sha(b):
    return hashlib.sha256(b).hexdigest()


def say(m):
    print(m, flush=True)


def die(m):
    say(f"\n✗ ABORTED — {m}\n  Nothing was changed.")
    sys.exit(1)


args = sys.argv[1:]
repo = os.path.abspath(os.path.expanduser(args[args.index("--repo") + 1])) if "--repo" in args else os.getcwd()
if not os.path.isdir(os.path.join(repo, "backend", "app")):
    alt = os.path.expanduser("~/dev/scalp-app")
    if os.path.isdir(os.path.join(alt, "backend", "app")):
        repo = alt
    else:
        die(f"{repo} is not the scalp-app repo (no backend/app) — pass --repo PATH")
say(f"repo: {repo}\nfence: {FENCE}")


def targets():
    """(item, absolute path, is_build_copy)"""
    out = []
    for it in ITEMS:
        out.append((it, os.path.join(repo, it["path"]), False))
        for a, b in BUILD_COPIES.items():
            if it["path"].startswith(a):
                p = os.path.join(repo, b + it["path"][len(a):])
                if os.path.isdir(os.path.dirname(p)):
                    out.append((it, p, True))
    return out


# ── rollback mode ────────────────────────────────────────────────────
if "--rollback" in args:
    n = 0
    for it, p, _ in targets():
        bak = p + ".bak-" + FENCE
        if os.path.exists(bak):
            shutil.copy2(bak, p)
            os.remove(bak)
            n += 1
        elif it["orig"] is None and os.path.exists(p):
            with open(p, "rb") as f:
                if sha(f.read()) == it["new"]:
                    os.remove(p)
                    n += 1
    say(f"rolled back {n} file(s)")
    sys.exit(0)

# ── 1. state of every target ─────────────────────────────────────────
plan, done, skipped = [], 0, []
for it, p, build in targets():
    cur = open(p, "rb").read() if os.path.exists(p) else None
    cs = sha(cur) if cur is not None else None
    rel = os.path.relpath(p, repo)
    if cs == it["new"]:
        done += 1
        continue
    if cs == it["orig"]:
        plan.append((it, p, cur, build))
        continue
    if build:
        skipped.append(rel)              # a stale build copy — the build re-syncs it
        continue
    if cur is None:
        die(f"{rel} is missing")
    die(f"{rel} differs from GitHub main and from the patched version — local edits? "
        f"(commit/stash them or pull main, then re-run)")
if not plan:
    say(f"✓ already applied ({done} file(s) carry {FENCE}) — nothing to do")
    sys.exit(0)

# ── 2. git status: an uncommitted change on a target is a stop sign ──
if "--allow-dirty" not in args:
    try:
        rels = [os.path.relpath(p, repo) for _, p, _, b in plan if not b]
        st = subprocess.run(["git", "status", "--porcelain", "--"] + rels, cwd=repo,
                            capture_output=True, text=True, timeout=30).stdout
        dirty = [l for l in st.splitlines() if l[:2].strip() and not l.startswith("??")]
        if dirty:
            die("uncommitted changes on target files:\n  " + "\n  ".join(dirty) + "\n  (re-run with --allow-dirty to override)")
    except FileNotFoundError:
        say("  (git not found — skipping the status check)")

# ── 3. decode + compile every payload before writing anything ───────
tmp = tempfile.mkdtemp(prefix="tsg_wing_guard_")
blobs = {}
for it in ITEMS:
    b = zlib.decompress(base64.b64decode(it["blob"]))
    if sha(b) != it["new"]:
        die(f"payload for {it['path']} is corrupt")
    blobs[it["path"]] = b
    if it["path"].endswith(".py"):
        f = os.path.join(tmp, os.path.basename(it["path"]))
        open(f, "wb").write(b)
        try:
            py_compile.compile(f, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"payload {it['path']} does not compile: {e}")
say(f"payloads verified and compiled ({len(ITEMS)} files)")

# ── 4. write, all or nothing ─────────────────────────────────────────
written = []


def restore():
    for p, old in reversed(written):
        try:
            if old is None:
                os.remove(p)
            else:
                open(p, "wb").write(old)
            bak = p + ".bak-" + FENCE
            if os.path.exists(bak):
                os.remove(bak)
        except Exception as e:
            say(f"  !! could not restore {p}: {e}")


try:
    for it, p, cur, build in plan:
        if cur is not None:
            open(p + ".bak-" + FENCE, "wb").write(cur)
        t = p + ".tmp-" + FENCE
        open(t, "wb").write(blobs[it["path"]])
        os.replace(t, p)
        written.append((p, cur))
        say(f"  wrote {os.path.relpath(p, repo)}{'  (build copy)' if build else ''}")
except Exception as e:
    restore()
    die(f"write failed ({e!r}) — everything restored")
for s_ in skipped:
    say(f"  skipped stale build copy {s_} (the next build re-syncs it)")

# ── 5. tests ─────────────────────────────────────────────────────────
backend = os.path.join(repo, "backend")
py = next((c for c in (os.path.join(backend, "venv", "bin", "python"), os.path.join(backend, ".venv", "bin", "python"),
                       os.path.join(repo, "venv", "bin", "python"), os.path.join(repo, ".venv", "bin", "python"))
           if os.path.exists(c)), sys.executable)
if "--skip-tests" in args:
    say("tests skipped (--skip-tests)")
else:
    say(f"running tests with {py}")
    env = dict(os.environ, PYTHONPATH=backend)
    failed, envmiss = [], []
    for t in TESTS:
        if not os.path.exists(os.path.join(backend, t)):
            continue
        try:
            r = subprocess.run([py, t], cwd=backend, env=env, capture_output=True, text=True, timeout=600)
            outp = (r.stdout or "") + (r.stderr or "")
        except subprocess.TimeoutExpired:
            r, outp = None, "timeout"
        last = (outp.strip().splitlines() or [""])[-1]
        if r is not None and r.returncode == 0:
            say(f"  ✓ {t}  {last}")
        elif "ModuleNotFoundError" in outp and "No module named 'app" not in outp:
            envmiss.append(t)
            say(f"  ? {t}  could not run here: {last}")
        else:
            failed.append(t)
            say(f"  ✗ {t}\n" + "\n".join("      " + l for l in outp.strip().splitlines()[-25:]))
    if failed:
        restore()
        die("tests failed: " + ", ".join(failed) + " — every file restored")
    if envmiss:
        say("  note: some suites need the backend's Python packages; re-run them with that Python")

shutil.rmtree(tmp, ignore_errors=True)
say(f"\n✓ {FENCE} applied ({len(written)} file(s)). Next: ./desktop/build-scalp.sh both, then restart the app.")
say("  Undo: python3 apply_tsg_wing_guard.py --rollback")
